def pattern_blocks(grid, include_zero=False):
    """The patterned sub-blocks of the grid, split by uniform lines of separator colors (colors appearing only in uniform lines)."""
    ur, uc = uniform_lines(grid, include_zero)
    h, w = len(grid), len(grid[0])
    sep = {grid[i][0] for i in ur} | {grid[0][j] for j in uc}
    sep = {c for c in sep if all(i in ur or j in uc for i in range(h) for j in range(w) if grid[i][j] == c)}
    rows = [i for i in range(h) if not (i in ur and grid[i][0] in sep)]
    cols = [j for j in range(w) if not (j in uc and grid[0][j] in sep)]
    return [[[[grid[i][j] for j in c] for i in r] for c in index_runs(cols)] for r in index_runs(rows)]

